def sequential_search(arr: list[int], target: int) -> tuple[bool, int]:
    # Iterate through each element in the array
    for index in range(len(arr)):
        # Check if the current element matches the target
        if arr[index] == target:
            # If found, return True along with the index
            return True, index
    # If not found after checking all elements, return False and -1
    return False, -1

def first_repeated_char(input_string):
    """
    Identifies the first repeating character within the provided string.

    :param input_string: String to scan for duplicate characters.
    :return: The first character that appears more than once, or None if no duplicates exist.
    """
    character_tracker = {}
    for character in input_string:
        if character in character_tracker:
            return character
        character_tracker[character] = True
    return None

