def frequency_lists(nested_array):
    """
    Calculate the frequency of each unique element within a nested list, returning a dictionary with elements as keys and their counts as values.

    :param nested_array: A list containing other lists of integers
    :return: A dictionary mapping each unique integer to its frequency in the nested array
    """
    element_count = {}
    for sublist in nested_array:
        for element in sublist:
            if element not in element_count:
                element_count[element] = 0
            element_count[element] += 1

    return element_count

